import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Create plane geometry (512×320 aspect ratio = 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1);

  // Load texture
  const textureAsset = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material with TSL nodes
  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = texture(textureAsset);

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transformation from config
  const pos = config.scenePosition || [0, 0, 0];
  const rot = config.sceneRotation || [0, 0, 0];
  const scl = config.sceneScale || [1, 1, 1];

  mesh.position.set(pos[0], pos[1], pos[2]);
  mesh.rotation.set(rot[0], rot[1], rot[2]);
  mesh.scale.set(scl[0], scl[1], scl[2]);

  // Store original Y position for animations
  const originalY = mesh.position.y;
  let hoverTimeline;

  // Attach event handlers
  mesh.userData.handlers = {};

  // Hover event: rise-in (y +0.15, power3.out, 0.7s)
  mesh.userData.handlers.hover = (isEntering) => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(mesh.position, {
      y: isEntering ? originalY + 0.15 : originalY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  // Click event: emit hub-journal.select
  mesh.userData.handlers.click = () => {
    const emitter = config.eventEmitter || ctx.eventEmitter;
    if (emitter?.emit) {
      emitter.emit('hub-journal.select');
    }
  };

  // Apply cinematic primitives
  const primitives = config.cinematicPrimitives || [];
  for (const prim of primitives) {
    if (ctx.primitives?.[prim.name]) {
      ctx.primitives[prim.name](mesh, prim.params || {});
    }
  }

  // Cleanup function
  mesh.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    geometry.dispose();
    material.dispose();
    textureAsset.dispose();
  };

  return mesh;
}
